n("רייזל", "רייזל היא צורה יידית של המילה רויז, ורד, עם סיומת של הקטנה, ומכאן הפירוש ורד קטן. בגרמנית המילה לוורד דומה לה מאוד. השם היה מוכר בקהילות אשכנז, ובעברית הפירוש שלו קרוב לשם ורד. ריזל הוא כתיב אחר של אותו שם.", ["ריזל"])
n("אילון", "אילון בנוי על המילה אלון, עץ גבוה וחזק עם עלים קשים, שגדל בארץ בחורש של הגליל, הכרמל והגולן. בספר שופטים אילון הזבולוני הוא אחד השופטים, איש משבט זבולון. בעברית האלון הוא תמונה מוכרת של חוזק ושל יציבות.", ["אלון"])
n("בצלאל", "בצלאל מחבר את המילים בצל ואל, ופירושו בצילו של אלוהים, כלומר תחת חסותו. בספר שמות בצלאל בן אורי הוא האומן שבנה את המשכן ואת כליו, והוא מתואר כמי שמלא חכמה ותבונה במלאכה. על שמו נקראת בצלאל, האקדמיה לאמנות ולעיצוב בירושלים.")
n("ג'ולאן", "ג'ולאן הוא השם הערבי של רמת הגולן, הרמה שבצפון מזרח הארץ, מעל הכנרת ועמק החולה. בעברית ובערבית שם המקום נשמע כמעט אותו דבר, ומקורו עתיק. בעברית אותו מקום נקרא גולן, וגם גולן הוא שם פרטי.", ["גולן"])
n("זכריא", "זכריא הוא הצורה הערבית של השם זכריה, שמחבר את המילה זכר עם יה, ופירושו ה׳ זכר. זכריה הוא שמו של אחד הנביאים, ובקוראן זכריא הוא אביו של יחיא, יוחנן המטביל. השם עבר מעברית לערבית, וכמו שמות רבים של נביאים קיבל בה צורה משלו.", ["זכריה"])
n("יונה", "יונה היא ציפור שחיה בארץ בערים, בכפרים ובשדות, ונחשבת לציפור עדינה ושקטה. בסיפור המבול היונה חוזרת אל התיבה עם עלה זית, ומכאן היונה כסמל של שלום. יונה הוא גם שמו של הנביא שנבלע בבטן של דג גדול. יונס הוא הצורה הערבית של השם.", ["יונס"])
n("אמין", "אמין היא מילה שפירושה נאמן, מי שאפשר לסמוך על דבריו. היא באה מהשורש א־מ־נ, שקיים גם בעברית וגם בערבית, ומאותו שורש באות בעברית המילים אמונה, נאמן ואמן. אמינה היא הצורה של השם בלשון נקבה.", ["אמינה"])
n("גור", "גור הוא הצאצא הצעיר של אריה, וגם של חיות טרף אחרות כמו זאב ודוב. בתורה, בברכת יעקב לבניו, יהודה משול לגור אריה. בעברית של היום המילה משמשת גם לגורים של כלבים ושל חתולים. מאותה מילה נבנה גם השם גורי.", ["גורי"])
n("דולב", "דולב הוא עץ גבוה עם גזע בהיר, קליפה שמתקלפת בפיסות ועלים רחבים שנושרים בחורף. בארץ הדולב המזרחי גדל בר לאורך נחלים בצפון, ובזכות העלים הרחבים הוא נותן צל רחב. בשפות אירופה הוא נקרא פלטנוס, שם שבא מיוונית.")
n("זואי", "זואי היא המילה היוונית לחיים, ומאותו מקור באות בשפות רבות מילים כמו זואולוגיה, חקר בעלי החיים. השם היה מוכר כבר ביוון העתיקה, ומשם עבר לשפות רבות באירופה. בעברית הפירוש שלו קרוב לשם חיים.")
n("לירוי", "לירוי הוא שם שמקורו בצירוף הצרפתי לה רואה, המלך. המילה הצרפתית רואה באה מהמילה הלטינית רקס, מלך. השם עבר מצרפתית לאנגלית, ובה הוא מוכר כשם פרטי, ומשם הגיע לשפות נוספות.")
n("סנא", "סנא היא מילה ערבית שפירושה זוהר, האור החזק שבוקע מדבר מבריק. בערבית המילה מתארת גם את ההבזק של ברק, שמאיר לרגע את השמים בלילה. השם קצר, ובעברית הוא נכתב בשלוש אותיות.")
n("תגל", "תגל היא צורה של הפועל לגיל, לשמוח, ופירושה היא תשמח. בספר ישעיהו הערבה, המדבר היבש, מתוארת כמי שתגל ותפרח כמו פרח. מאותו שורש, ג־י־ל, באות גם המילים גיל וגילה, ובעברית של היום הן מתארות שמחה גדולה.")
n("בלאל", "בלאל הוא שם ערבי עתיק, שמקובל לקשר לשורש ב־ל־ל, שעניינו לחות ורעננות. בערבית מאותו שורש באה גם מילה למים שמרווים את הצמא, ומכאן הפירוש שמקובל לתת לשם. השם מוכר בשפה הערבית מראשית האסלאם.")
n("לינוי", "לינוי מחבר את המילים לי ונוי, ופירושו היופי שלי. נוי הוא יופי וקישוט, ובעברית של היום המילה מוכרת בצירופים כמו גינת נוי ועצי נוי, עצים שנוטעים בשביל היופי שלהם. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־לי, כמו ליאור וליאב.")
n("נסיה", "נסיה מחבר את המילה נס עם יה, קיצור של שם ה׳, ופירושו נס של ה׳. בעברית העתיקה נס הוא גם דגל, תורן גבוה שמניפים כדי שיראו אותו מרחוק, ובעברית של היום הוא בעיקר דבר מופלא שקורה בלי שציפו לו. מאותה מילה נבנה גם השם נס.", ["נס"])
n("רובי", "רובי היא המילה האנגלית לאבן אודם, אבן חן אדומה ושקופה שמשמשת לתכשיטים. המילה באה מהמילה הלטינית רובר, אדום. רובי הוא גם צורת חיבה של השם ראובן, ולכן יש לשם שני מקורות שונים לגמרי.", ["ראובן"])
n("אלינור", "אלינור הוא שם אירופי עתיק, שעבר מצרפתית לאנגלית, ומקורו אינו ודאי. בעברית אפשר לקרוא בו את המילים אלי ונור, אלוהיי אור, כי בערבית נור הוא אור, ומאותו שורש באה בעברית המילה מנורה. נלי היא צורת חיבה של השם.", ["נלי"])
n("ליאב", "ליאב מחבר את המילים לי ואב, ופירושו יש לי אב. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־לי, כמו ליאור וליעד. שמות שבנויים על המילה אב מוכרים בעברית מימי קדם, למשל אביאל ואבישי.")
n("מישל", "מישל הוא הצורה הצרפתית של השם מיכאל, שפירושו מי כמו אל. בצרפתית יש לשם שתי צורות שנשמעות אותו דבר, אחת לבנים ואחת לבנות, ובכתב הצרפתי הן נבדלות בסופן. השם עבר מצרפתית לשפות רבות, ומיכאל הוא הצורה העברית שלו.", ["מיכאל"])
n("סלים", "סלים היא מילה ערבית שפירושה שלם ובריא, מי שאין בו פגם. היא באה מהשורש ס־ל־מ, שהוא אותו שורש של המילה העברית שלום, ומאותו שורש באות בערבית גם המילים סלאם וסלאמה. בערבית המילה מתארת גם דבר שנשמר בלי נזק.")
n("אילת", "אילת היא העיר שבקצה הדרומי של הארץ, על חוף מפרץ אילת בים סוף. בתורה, בתיאור הדרך של בני ישראל במדבר, אילת מוזכרת לצד עציון גבר. מקור השם אינו ודאי. ליד העיר נמצאת שמורת חוף האלמוגים, עם שונית של אלמוגים ודגים צבעוניים.")
n("ברק", "ברק הוא הבזק האור שמופיע בשמים בזמן סערה, ואחריו נשמע הרעם. בספר שופטים ברק בן אבינועם הוא המצביא שיצא יחד עם דבורה הנביאה למלחמה נגד סיסרא. מאותו שורש, ב־ר־ק, באות גם המילים מבריק וברקת, אבן חן ירוקה.")
n("דר", "דר היא אבן יקרה, ויש מפרשים שהיא פנינה או סוג של שיש מבריק. בספר אסתר הדר מופיעה ברשימה של אבנים יקרות שמהן הייתה עשויה הרצפה בארמון המלך בשושן. השם קצר ופשוט, והוא ניתן לבנים ולבנות.")
n("גולדה", "גולדה היא צורה יידית של המילה גאלד, זהב, ובגרמנית ובאנגלית המילה לזהב דומה לה מאוד. השם היה מוכר בקהילות אשכנז, ובעברית הפירוש שלו קרוב לשם זהבה. גולדי היא צורת חיבה של אותו שם.", ["גולדי"])
n("גולן", "גולן הוא שמה של הרמה שבצפון מזרח הארץ, מעל הכנרת ועמק החולה. בתורה גולן היא אחת מערי המקלט, עיר בבשן שאליה יכול היה לברוח מי שהרג אדם בלי כוונה. ג'ולאן הוא השם הערבי של אותו מקום.", ["ג'ולאן"])
n("יעקוב", "יעקוב הוא הצורה הערבית של השם יעקב, שמו של אחד מאבות האומה. בתורה השם נקשר למילה עקב, כי בלידתו יעקב אחז בעקב של אחיו עשו. בקוראן יעקוב מופיע בין הנביאים, וכמו שמות רבים של נביאים השם קיבל בערבית צורה משלו.", ["יעקב"])
n("נלי", "נלי היא צורת חיבה של השמות אלינור והלן, ובאנגלית היא מוכרת גם כצורת חיבה של שמות אחרים שיש בהם הצליל אל. היום נלי משמשת גם כשם בפני עצמו. בעברית אפשר לשמוע בה דמיון לשם נילי, אבל אין קשר בין השניים.", ["אלינור"])
n("סלאח", "סלאח היא מילה ערבית שפירושה יושר וטוב, מצב שבו דבר הוא כמו שצריך להיות. היא באה משורש ערבי שעניינו טוב ותיקון, ומאותו שורש בא גם השם סאלח. בעברית השם נשמע קרוב למילה סליחה, אבל המשמעות הערבית שלו אחרת.")
n("אמירה", "לשם אמירה יש שני מקורות. בערבית אמירה היא נסיכה, הצורה של המילה אמיר בלשון נקבה, ובעברית אמירה היא דבר שנאמר, מהשורש א־מ־ר. בעברית העתיקה אמיר הוא גם הענף שבראש העץ. אמיר הוא הצורה של השם בלשון זכר.", ["אמיר"])
n("באסל", "באסל היא מילה ערבית שפירושה אמיץ, מי שלא נרתע מול סכנה. היא באה מהשורש ב־ס־ל, שעניינו אומץ ותקיפות, ומאותו שורש באה בערבית גם המילה בסאלה, גבורה. בעברית הפירוש שלו קרוב למילה גיבור.")
n("דילן", "דילן הוא שם וולשי עתיק, והוא מופיע באגדות הוולשיות של ימי הביניים כשמה של דמות שקשורה לים. מקובל לקשר את השם למילה הוולשית לים, אבל מקורו המדויק אינו ודאי. השם עבר מוולשית לאנגלית, ומשם לשפות נוספות.")
n("דימא", "דימא היא מילה ערבית לגשם שקט, שיורד לאט ולאורך זמן, בלי רעמים וברקים. גשם כזה מרווה את האדמה לעומק, בלי לסחוף אותה. בעברית קרובה אליה המילה רביבים, גשם קל ונעים שיורד בטיפות קטנות.")
n("חדיגה", None, note="Old Arabic name whose intro is only a famous person (Khadija); the word's literal meaning is not one to offer as a name story, so no story.")
n("עובדיה", "עובדיה מחבר את המילה עובד עם יה, קיצור של שם ה׳, ופירושו מי שעובד את ה׳. עובדיה הוא אחד מתרי עשר הנביאים, וספר קצר בתנ״ך נקרא על שמו. בספר מלכים עובדיה אחר מסתיר נביאים במערות כדי להציל אותם. מאותו שורש, ע־ב־ד, באות גם המילים עבודה ועובד.")
n("רחמה", "רחמה היא רחמים וחמלה, והמילה מוכרת גם בעברית וגם בערבית, שתי שפות שחולקות כאן שורש. השורש ר־ח־מ קשור למילה רחם, ומאותו שורש באות בעברית גם המילים רחמים, רחום ורחמנות. בערבית אל־רחמן הוא אחד מכינויי האל.")
n("גבע", "גבע היא גבעה, מקום שמתרומם מעל השטח שסביבו. גבע הוא גם שמו של קיבוץ בעמק יזרעאל, למרגלות הגלבוע. מאותו שורש, ג־ב־ע, באות גם המילים גבעה וגבעול, הגבעול של צמח שמתרומם מהאדמה.")
n("האני", "האני היא מילה ערבית שפירושה מאושר ושמח, מי שטוב לו. היא באה מהשורש ה־נ־א, ומאותו שורש באה בערבית גם הברכה הניאן, שאומרים למי שאוכל או שותה, כמו לבריאות בעברית. השם קצר, ובעברית הוא נכתב בארבע אותיות.")
n("טוביה", "טוביה מחבר את המילה טוב עם יה, קיצור של שם ה׳, ופירושו ה׳ הוא הטוב שלי. בספר זכריה טוביה הוא אחד מהגולים שחזרו מבבל. מאותו שורש, ט־ו־ב, באות גם המילים טובה ומיטב, ומאותה מילה נבנו גם טובי וטובה.", ["טובי", "טובה"])
n("קרני", "קרני פירושו הקרן שלי, והשם בנוי על המילה קרן עם סיומת של שייכות. בעברית קרן היא גם קרן אור, פס של אור שנשלח למרחק, וגם הקרן של בעל חיים. מאותו שורש, ק־ר־נ, באות גם המילים קורן וקרינה.", ["קרן"])
n("תאופיק", "תאופיק היא מילה ערבית שפירושה הצלחה, דבר שעולה יפה. היא באה מהשורש ו־פ־ק, שעניינו התאמה, ומאותו שורש באה בערבית גם המילה מוופק, מי שהצליח. בערבית של היום אומרים בתאופיק כשמאחלים למישהו הצלחה.")
n("ביאן", "ביאן היא מילה ערבית שפירושה בהירות, היכולת לומר דבר בצורה ברורה ויפה. היא באה מהשורש ב־י־נ, שעניינו הבהרה, ובעברית קרובות אליה המילים בין ובינה. בערבית הביאן הוא גם תחום בתורת הלשון, שעוסק ביופי של הדיבור.")
n("גלעד", "גלעד הוא שמו של אזור הרים ממזרח לירדן, בשטח של ממלכת ירדן של היום. בספר בראשית יעקב ולבן מקימים גל של אבנים לעדות על הברית ביניהם, ויעקב קורא לו גלעד, כלומר גל עד. מאותו שורש, ע־ו־ד, באות גם המילים עד ועדות.")
n("יאסר", "יאסר היא מילה ערבית שפירושה קלות ונוחות, מצב שבו דבר נעשה בלי קושי. היא באה מהשורש י־ס־ר, ומאותו שורש באה בערבית גם המילה יוסר, קלות, שהיא ההפך מקושי. בעברית הפירוש שלו קרוב למילה נוחות.")
n("ליעד", "ליעד מחבר את המילים לי ועד, ופירושו שלי לעד, כלומר לתמיד. בעברית העתיקה עד הוא זמן ארוך מאוד, בלי סוף, כמו בצירוף לעולם ועד. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־לי, כמו ליאור וליאב.")
n("מונא", "מונא היא מילה ערבית שפירושה משאלות ותקוות, הדברים שאדם מקווה שיקרו. היא באה מהשורש מ־נ־י, ומאותו שורש באה בערבית גם המילה אומניה, משאלה. השם קצר, ובעברית הוא נכתב בארבע אותיות.")
n("סיראג'", "סיראג' היא המילה הערבית למנורה, ובמיוחד למנורת שמן שמאירה בחושך. בקוראן המילה מתארת גם את השמש, כמו מנורה גדולה בשמים. בעברית הפירוש שלו קרוב לשמות כמו נר ונורי.")
n("סתיו", "סתיו היא העונה שבין הקיץ לחורף, שבה הימים מתקצרים והגשם הראשון, היורה, יורד. בארץ הסתיו מתחיל לרוב עם פריחת החצבים, ואחריהם פורחות הסתווניות, שנקראו על שם העונה. השם ניתן לבנים ולבנות.")
n("עאישה", "עאישה היא מילה ערבית שפירושה חיה, מי שחיה. היא באה מהשורש ע־י־ש, שעניינו חיים, ומאותו שורש באה בערבית גם המילה עיש, שפירושה חיים, ובערבית המצרית גם לחם. בעברית הפירוש שלה קרוב לשם חיה.")
n("יער", "יער הוא שטח גדול שעצים רבים גדלים בו צפופים זה לזה. בארץ יש חורש טבעי של אלונים בגליל ובכרמל, ויערות רבים ניטעו במאה העשרים, למשל יער בן שמן ויער ירושלים. מאותה מילה נבנו גם יערה ויערי.", ["יערה", "יערי"])
n("עזרא", "עזרא היא הצורה הארמית של המילה עזרה, תמיכה למי שצריך. עזרא הסופר, שספר בתנ״ך נקרא על שמו, עלה מבבל לירושלים ולימד את העם תורה. מאותו שורש, ע־ז־ר, באות גם המילים עוזר ועזרה, ומאותו שורש נבנו גם עזריאל ואליעזר.")
n("עמאר", "עמאר היא מילה ערבית שפירושה מי שבונה ומיישב, מי שהופך מקום שומם למקום שיש בו חיים. היא באה מהשורש ע־מ־ר, ומאותו שורש באות בערבית גם המילים עמארה, בניין, ועומראן, יישוב ובנייה.")
n("פלא", "פלא הוא דבר מופלא, שקשה להבין או להסביר אותו. בספר ישעיהו פלא הוא אחד הכינויים בשם הארוך של הילד שהנביא מבשר על לידתו. מאותו שורש, פ־ל־א, באות גם המילים נפלא והפלאה, ובעברית של היום אומרים לא פלא כשמשהו ברור מאליו.")
n("רם", "רם הוא מי שגבוה ונעלה, ובעברית המילה מתארת גם קול חזק, כמו בצירוף בקול רם. מאותו שורש, ר־ו־מ, באות גם המילים רום, מרום והרמה. מאותה מילה נבנו גם יורם ואלירם, שפירושם ה׳ רם ואלוהיי רם.", ["יורם", "אלירם"])
n("וסאם", "וסאם היא מילה ערבית לעיטור, אות כבוד שמעניקים למי שעשה מעשה ראוי. היא באה מהשורש ו־ס־מ, שעניינו סימון, ומאותו שורש באה בערבית גם המילה וסים, נאה ויפה פנים.")
n("ירחמיאל", "ירחמיאל מחבר את הפועל ירחם עם אל, ופירושו אלוהים ירחם. בספר ירמיהו ירחמיאל בן המלך הוא אחד השליחים שנשלחו לתפוס את ברוך הסופר ואת ירמיהו. מאותו שורש, ר־ח־מ, באות גם המילים רחמים ורחום.")
n("רוחמה", "רוחמה היא מי שזוכה לרחמים, מי שאחרים מרחמים עליה. השם בא מהשורש ר־ח־מ, שממנו באות גם המילים רחמים, רחום ורחמנות. רחמה, שם שבנוי על אותו שורש, מוכרת גם בעברית וגם בערבית.")
n("אווה", "אווה היא הצורה של השם חוה בשפות רבות באירופה, והיא הגיעה אליהן דרך התרגום הלטיני. בעברית השם חוה קשור למילה חי, ומכאן הפירוש מקור החיים. בשפות שונות השם נכתב ונהגה מעט אחרת, למשל אווה ואיב.", ["חוה"])
n("ג'וליה", "ג'וליה היא הצורה האנגלית והאיטלקית של השם הרומי יוליה, הצורה של השם יוליוס בלשון נקבה. יוליוס היה שמה של משפחה רומית עתיקה, ומקורו אינו ודאי. ג'ולי היא הצורה הצרפתית של אותו שם, וג'וליא היא כתיב אחר שלו.", ["ג'ולי", "ג'וליא"])
n("פריידא", "פריידא היא צורה יידית של המילה פרייד, שמחה, ובגרמנית המילה לשמחה דומה לה מאוד. השם היה מוכר בקהילות אשכנז, ובעברית הפירוש שלו קרוב לשמות כמו שמחה וגילה. פריידי היא צורת חיבה של אותו שם.", ["פריידי"])
n("איאת", "איאת היא צורת הרבים של המילה הערבית איה, שפירושה אות וסימן. בערבית המילה משמשת גם ליחידות הקצרות שמהן בנויות הסורות של הקוראן. בעברית קרובה אליה המילה אות, שגם היא מתארת סימן.")
n("אלישיב", "אלישיב מחבר את המילה אלי, אלוהיי, עם ישיב, ופירושו אלוהים ישיב. בספר נחמיה אלישיב הוא הכהן הגדול, שקם עם אחיו הכהנים ובנה את שער הצאן בחומת ירושלים. מאותו שורש, ש־ו־ב, באות גם המילים תשובה ושיבה.")
n("הוד", "הוד הוא הדר ותפארת, יופי שמעורר כבוד. בספר תהילים הוד והדר מופיעים יחד, צמד מילים שמתאר גדולה ויופי. בעברית של היום המילה מוכרת בצירוף הוד מלכותו, ומאותה מילה בא גם שמה של העיר הוד השרון.")
n("חושן", "חושן הוא חלק מבגדי הכהן הגדול, לוח מרובע שענד על חזהו, ובו שתים עשרה אבנים יקרות. בתורה מתואר שעל כל אבן נחרט שמו של אחד משבטי ישראל. החושן נקרא גם חושן המשפט, והאורים והתומים נשמרו בתוכו.")
n("מוניר", "מוניר היא מילה ערבית שפירושה מאיר, מי שאור יוצא ממנו. היא באה מהשורש נ־ו־ר, ומאותו שורש באה גם המילה נור, אור, ובעברית קרובה אליה המילה מנורה. מונירה היא הצורה של השם בלשון נקבה.", ["מונירה"])

